insert into public.treatments(slug, name, specialty_id, category, description, aliases, overview, procedure_summary, indications, diagnostics, recovery, typical_stay_days, faqs, source_kind, publication_status, source_record_id) values ('knee-replacement', 'Knee Replacement', (select id from public.specialties where slug = 'orthopedics'), 'Joint care', 'A procedure category involving replacement of damaged knee joint surfaces.', array['knee surgery', 'knee joint replacement', 'total knee replacement']::text[], 'A procedure category involving replacement of damaged knee joint surfaces. This sample page organizes questions and options; a qualified clinician must assess individual suitability.', 'The exact approach to knee replacement depends on the patient''s condition, investigations, and specialist review. This is an overview of the care category, not a treatment plan.', 'A referral or existing diagnosis may prompt discussion of knee replacement. A clinician should review symptoms, history, and alternatives.', 'Assessment may involve a clinical examination and condition-specific reports or imaging. Ask the treating team which records are required.', 'Recovery time and follow-up vary by person and treatment. Discuss expected stay, rehabilitation, medication, and warning signs with the treating team.', 4, '[{"question":"How can I compare options for Knee Replacement?","answer":"Compare the proposed care plan, provider capability, total estimated cost, likely stay, and follow-up arrangements. Ask a qualified specialist which factors matter for your case."},{"question":"Is the displayed cost a quote?","answer":"No. All values in this demonstration are sample estimates. A provider must issue a current, case-specific quote."}]'::jsonb, 'synthetic', 'published', '00000000-0000-0000-0000-000000000001') on conflict (slug) do nothing;
